#include <bits/stdc++.h>
using namespace std;

const int INF = 1000000009;
typedef pair<int,int> pii;
typedef pair<pii,int> ppi;

struct Edge {
    int u, v, flow, cap;
    Edge(int u_, int v_, int f_, int c_) : u(u_), v(v_), flow(f_), cap(c_) {}
};

class Dinic {
public:
    int S, T;
    vector<vector<int>> g;
    vector<Edge> e;
    vector<int> ptr, level;

    Dinic(int n, int s, int t) : S(s), T(t), g(n), ptr(n), level(n) {}

    void addEdge(int u, int v, int c) {
        g[u].push_back((int)e.size());
        e.push_back(Edge(u, v, 0, c));
        g[v].push_back((int)e.size());
        e.push_back(Edge(v, u, 0, 0));
    }

    bool bfs() {
        fill(level.begin(), level.end(), -1);
        level[S] = 0;
        queue<int> q;
        q.push(S);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int id : g[u]) {
                int v = e[id].v;
                if (level[v] == -1 && e[id].flow < e[id].cap) {
                    level[v] = level[u] + 1;
                    q.push(v);
                    if (v == T) return true;
                }
            }
        }
        return false;
    }

    long long dfs(int u, int f) {
        if (f == 0) return 0;
        if (u == T) return f;
        for (int &i = ptr[u]; i < (int)g[u].size(); ++i) {
            int id = g[u][i];
            int v = e[id].v;
            if (level[v] != level[u] + 1) continue;
            long long pushed = dfs(v, min(f, e[id].cap - e[id].flow));
            if (pushed) {
                e[id].flow += (int)pushed;
                e[id ^ 1].flow -= (int)pushed;
                return pushed;
            }
        }
        return 0;
    }

    long long maxflow() {
        long long ans = 0;
        while (bfs()) {
            fill(ptr.begin(), ptr.end(), 0);
            while (long long pushed = dfs(S, INF)) ans += pushed;
        }
        return ans;
    }
};

int n, m;
char sci[101][101], rea[101][101];
int danger[101][101];

bool valid(int r, int c) { return r >= 0 && c >= 0 && r < n && c < m; }
int idOf(int x, int y) { return 1 + m * x + y; }

int main() {
    ios::sync_with_stdio(false);
    int deadline;
    cin >> n >> deadline;
    ++deadline;
    m = n;

    for (int i = 0; i < n; ++i) cin >> sci[i];

    queue<pii> q0;
    for (int i = 0; i < n; ++i) {
        cin >> rea[i];
        for (int j = 0; j < m; ++j) {
            danger[i][j] = INF;
            if (rea[i][j] == 'Z') {
                q0.push(pii(i, j));
                danger[i][j] = 1;
            }
        }
    }

    while (!q0.empty()) {
        int x = q0.front().first;
        int y = q0.front().second;
        q0.pop();
        for (int dx = -1; dx <= 1; ++dx) {
            for (int dy = -1; dy <= 1; ++dy) {
                if (abs(dx) + abs(dy) != 1) continue;
                int nx = x + dx, ny = y + dy;
                if (valid(nx, ny) && danger[nx][ny] == INF && sci[nx][ny] != 'Y') {
                    danger[nx][ny] = danger[x][y] + 1;
                    q0.push(pii(nx, ny));
                }
            }
        }
    }

    int src = 0;
    int snk = n * n + n * n + 1;
    Dinic flow(n * n * 2 + 2, src, snk);

    for (int x = 0; x < n; ++x) {
        for (int y = 0; y < m; ++y) {
            if (sci[x][y] >= '1' && sci[x][y] <= '9')
                flow.addEdge(src, idOf(x, y), sci[x][y] - '0');
            if (rea[x][y] >= '1' && rea[x][y] <= '9')
                flow.addEdge(n * n + idOf(x, y), snk, rea[x][y] - '0');

            for (int X = 0; X < n; ++X) {
                for (int Y = 0; Y < m; ++Y) {
                    if (sci[x][y] == 'Y' || sci[x][y] == 'Z' || rea[X][Y] == 'Y' || rea[X][Y] == 'Z')
                        continue;

                    bool seen[101][101] = {};
                    queue<ppi> q1;
                    q1.push(ppi(pii(x, y), 1));
                    seen[x][y] = true;
                    while (!q1.empty()) {
                        int cx = q1.front().first.first;
                        int cy = q1.front().first.second;
                        int tim = q1.front().second;
                        q1.pop();
                        if (cx == X && cy == Y) {
                            seen[X][Y] = true;
                            break;
                        }
                        if (tim >= danger[cx][cy] || tim >= deadline) continue;
                        for (int dx = -1; dx <= 1; ++dx) {
                            for (int dy = -1; dy <= 1; ++dy) {
                                if (abs(dx) + abs(dy) != 1) continue;
                                int nx = cx + dx, ny = cy + dy;
                                if (valid(nx, ny) && !seen[nx][ny] &&
                                    sci[nx][ny] != 'Y' && sci[nx][ny] != 'Z' &&
                                    tim + 1 <= danger[nx][ny]) {
                                    seen[nx][ny] = true;
                                    q1.push(ppi(pii(nx, ny), tim + 1));
                                }
                            }
                        }
                    }
                    if (seen[X][Y])
                        flow.addEdge(idOf(x, y), n * n + idOf(X, Y), INF);
                }
            }
        }
    }

    cout << flow.maxflow() << endl;
    return 0;
}
